import { flushPromises, mount } from '@vue/test-utils'
import { createI18n } from 'vue-i18n'
import { afterEach, describe, expect, it, vi } from 'vitest'

import ChannelFormModal from '@/components/console/channels/ChannelFormModal.vue'
import type { TaskPluginOption } from '@/features/task-plugins/types'
import type { AdminChannel } from '@/types/console'
// Generated by controller/frontend_contract_test.go from requests that the real
// UpdateChannel handler accepts.
import rootRename from '../../../../../tests/fixtures/native/channel-task-plugin-rename.put.request.json'
import adminRename from '../../../../../tests/fixtures/native/channel-task-plugin-rename-write-only.put.request.json'
import convert from '../../../../../tests/fixtures/native/channel-new-api-to-task-plugin.put.request.json'

const permissions = vi.hoisted(() => ({ sensitive: true, bind: true }))
vi.mock('@/api/adminManagement', () => ({
  metadataApi: { groups: vi.fn().mockResolvedValue([]) },
}))
vi.mock('@/stores/auth', () => ({
  useAuthStore: () => ({
    isAdmin: true,
    hasPermission: (resource: string, action: string) =>
      (resource === 'channel' &&
        (action === 'write' ||
          action === 'read' ||
          (action === 'sensitive_write' && permissions.sensitive))) ||
      (resource === 'task_plugin' && action === 'bind' && permissions.bind),
  }),
}))
vi.mock('@/stores/app', () => ({
  useAppStore: () => ({
    isFeatureEnabled: () => true,
    featureStatus: () => 'live',
  }),
}))
const pluginOptions = vi.hoisted(() =>
  ['contract-plugin', 'alpha', 'beta', 'gamma'].map(
    (key): TaskPluginOption => ({
      key,
      name: key,
      models: ['doc'],
      upstreams: ['new_api'],
      baseUrl: 'https://plugin.example.com',
    })
  )
)
vi.mock('@/features/task-plugins/api', () => ({
  getTaskPluginOptions: vi.fn().mockResolvedValue(pluginOptions),
}))

function channel(overrides: Partial<AdminChannel>): AdminChannel {
  return {
    id: rootRename.id,
    name: 'plugin-contract',
    type: 61,
    channel_ratio: '1',
    max_concurrency: 0,
    in_flight: 0,
    lab: { id: 'unknown', name: 'unknown', source: 'unknown' },
    status: 1,
    priority: 0,
    weight: 1,
    used_quota: 0,
    balance: 0,
    response_time: 0,
    test_time: 0,
    base_url: 'https://plugin.example.com',
    models: 'doc',
    model_mapping: '',
    setting: '{"task_plugin_key":"contract-plugin"}',
    ...overrides,
  }
}
const newApi = channel({
  type: 60,
  setting:
    '{"force_format":true,"task_plugin_key":"alpha","task_extend_plugin_keys":["beta"]}',
})

const query = <T extends Element>(selector: string) =>
  document.body.querySelector<T>(`[role="dialog"] ${selector}`)

let wrapper: { unmount: () => void } | null = null
function unmount() {
  wrapper?.unmount()
  wrapper = null
  document.body.innerHTML = ''
}
async function openForm(editing: AdminChannel | null) {
  const save = vi.fn().mockResolvedValue(true)
  wrapper = mount(ChannelFormModal, {
    attachTo: document.body,
    props: { open: true, editing, save, fetchModels: vi.fn() },
    global: {
      plugins: [
        createI18n({
          legacy: false,
          locale: 'en',
          missingWarn: false,
          fallbackWarn: false,
        }),
      ],
    },
  })
  await flushPromises()
  return save
}

async function saveAs(name: string, save: ReturnType<typeof vi.fn>) {
  const input = query<HTMLInputElement>('input[name="admin-channel-name"]')!
  input.value = name
  input.dispatchEvent(new Event('input'))
  await flushPromises()
  ;[
    ...document.body.querySelectorAll<HTMLButtonElement>(
      '[role="dialog"] button'
    ),
  ]
    .find((button) => button.textContent?.includes('channels.saveChannel'))!
    .click()
  await flushPromises()
  expect(save).toHaveBeenCalledOnce()
  // useAdminChannels.updateChannelDetails adds the id before the PUT.
  return { id: rootRename.id, ...save.mock.calls[0]![0] }
}

const selectedPlugins = () =>
  [
    ...(query<HTMLSelectElement>('select[multiple]')?.selectedOptions ?? []),
  ].map((option) => option.value)

afterEach(() => {
  unmount()
  permissions.sensitive = true
  permissions.bind = true
})

describe('task plugin channel edits', () => {
  it('resends the unchanged type 61 binding for a sensitive writer', async () => {
    const save = await openForm(channel({}))
    expect(selectedPlugins()).toEqual(['contract-plugin'])
    expect(await saveAs(rootRename.name, save)).toEqual(rootRename)
  })

  it('edits a type 61 channel without bind through the write-only path', async () => {
    permissions.bind = false
    const save = await openForm(channel({}))
    expect(query('select[multiple]')).toBeNull()
    expect(await saveAs(adminRename.name, save)).toEqual(adminRename)
  })

  it('offers the task plugin type only with bind', async () => {
    const typeLabels = async () => {
      query<HTMLButtonElement>('button[aria-expanded]')!.click()
      await flushPromises()
      return [
        ...document.body.querySelectorAll('[role="listbox"] [role="option"]'),
      ].map((option) => option.textContent?.trim())
    }
    // Each option also renders the vendor logo's fallback text.
    const taskPlugin = expect.stringMatching(/Task Plugin$/)
    await openForm(null)
    expect(await typeLabels()).toContainEqual(taskPlugin)
    unmount()
    permissions.bind = false
    await openForm(null)
    const labels = await typeLabels()
    expect(labels).toContainEqual(expect.stringMatching(/New API$/))
    expect(labels).not.toContainEqual(taskPlugin)
  })

  it('loads both New API binding fields and leaves an unchanged set unsent', async () => {
    const save = await openForm(newApi)
    expect(selectedPlugins()).toEqual(['alpha', 'beta'])
    expect(await saveAs('renamed', save)).not.toHaveProperty('setting')
  })

  it('converts the binding fields when New API becomes Task Plugin', async () => {
    const save = await openForm(
      channel({
        type: 60,
        setting:
          '{"force_format":true,"task_extend_plugin_keys":["contract-plugin"]}',
      })
    )
    expect(selectedPlugins()).toEqual(['contract-plugin'])
    query<HTMLButtonElement>('button[aria-expanded]')!.click()
    await flushPromises()
    ;[
      ...document.body.querySelectorAll<HTMLElement>(
        '[role="listbox"] [role="option"]'
      ),
    ]
      .find((option) => /Task Plugin$/.test(option.textContent?.trim() ?? ''))!
      .click()
    await flushPromises()
    expect(await saveAs(convert.name, save)).toEqual(convert)
  })

  it('rewrites only the binding fields when the New API set changes', async () => {
    const save = await openForm(newApi)
    const select = query<HTMLSelectElement>('select[multiple]')!
    for (const option of select.options)
      option.selected = option.value !== 'beta'
    select.dispatchEvent(new Event('change'))
    await flushPromises()
    const payload = await saveAs('rebound', save)
    expect(JSON.parse(payload.setting)).toEqual({
      force_format: true,
      task_extend_plugin_keys: ['contract-plugin', 'alpha', 'gamma'],
    })
  })

  it('hides the binding from a binder without sensitive write', async () => {
    permissions.sensitive = false
    const save = await openForm(newApi)
    expect(query('select[multiple]')).toBeNull()
    expect(await saveAs('renamed', save)).not.toHaveProperty('setting')
  })
})
